  "inlineSchema": "// Prisma schema file for BulSU Tradespace\n// Supabase PostgreSQL configuration with connection pooling & direct migration URL\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"./client\"\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\n// -----------------------------------------------------------------------\n// User — Supabase Auth handles password hashing & JWT.\n// supabaseId links this profile to the Supabase auth.users table.\n// Profile fields are optional at signup and filled in on the Profile page.\n// -----------------------------------------------------------------------\nmodel User {\n  id Int @id @default(autoincrement())\n\n  // --- Supabase Auth link (UUID from auth.users) ---\n  supabaseId String @unique // Supabase auth.users.id (UUID)\n\n  // --- Basic identity (required at signup) ---\n  email String @unique\n  name  String\n\n  // --- Role & Profile Completion ---\n  // role: \"student\" | \"faculty\" | \"staff\" — set during profile completion\n  role             String?\n  profileCompleted Boolean @default(false)\n\n  // --- Student-specific fields ---\n  studentId String? @unique // e.g. \"2022-108249\"\n  course    String? // e.g. \"BS Information Technology\"\n  year      String? // e.g. \"3rd Year\"\n\n  // --- Faculty/Staff shared fields ---\n  employeeId String? // e.g. \"EMP-2024-001\"\n  position   String? // e.g. \"Instructor I\", \"Administrative Officer\"\n  office     String? // e.g. \"Office of the Registrar\" (staff only)\n\n  // --- Shared profile fields ---\n  college String? // e.g. \"CIT / Engineering\"\n  campus  String  @default(\"Meneses Campus\")\n  phone   String? // e.g. \"0917-123-4567\"\n  bio     String?\n  avatar  String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  listings           Listing[]\n  claims             Claim[]\n  savedItems         SavedItem[]\n  notifications      Notification[] @relation(\"RecipientNotifications\")\n  actedNotifications Notification[] @relation(\"ActorNotifications\")\n\n  @@map(\"users\")\n}\n\nmodel Listing {\n  id          Int      @id @default(autoincrement())\n  status      String   @default(\"active\") // \"active\", \"sold\", \"draft\"\n  title       String\n  category    String\n  college     String\n  campus      String   @default(\"Meneses Campus\")\n  condition   String\n  description String   @db.Text\n  type        String   @default(\"For Sale\") // \"For Sale\", \"Item Swap\", \"Giveaway\", \"Service\"\n  price       Float    @default(0)\n  images      String[] // Array of image URLs or storage paths\n\n  sellerId Int\n  seller   User @relation(fields: [sellerId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  claims        Claim[]\n  savedBy       SavedItem[]\n  notifications Notification[]\n\n  @@map(\"listings\")\n}\n\nmodel Claim {\n  id         Int     @id @default(autoincrement())\n  listingId  Int\n  listing    Listing @relation(fields: [listingId], references: [id], onDelete: Cascade)\n  claimantId Int\n  claimant   User    @relation(fields: [claimantId], references: [id], onDelete: Cascade)\n\n  status    String   @default(\"pending\") // \"pending\", \"accepted\", \"declined\", \"completed\"\n  notes     String?  @db.Text\n  claimDate DateTime @default(now())\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  notifications Notification[]\n\n  @@map(\"claims\")\n}\n\nmodel SavedItem {\n  id        Int      @id @default(autoincrement())\n  userId    Int\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  listingId Int\n  listing   Listing  @relation(fields: [listingId], references: [id], onDelete: Cascade)\n  createdAt DateTime @default(now())\n\n  @@unique([userId, listingId])\n  @@map(\"saved_items\")\n}\n\nmodel Notification {\n  id        Int      @id @default(autoincrement())\n  userId    Int      @map(\"user_id\")\n  user      User     @relation(\"RecipientNotifications\", fields: [userId], references: [id], onDelete: Cascade)\n  actorId   Int?     @map(\"actor_id\")\n  actor     User?    @relation(\"ActorNotifications\", fields: [actorId], references: [id], onDelete: Cascade)\n  type      String\n  listingId Int?     @map(\"listing_id\")\n  listing   Listing? @relation(fields: [listingId], references: [id], onDelete: Cascade)\n  claimId   Int?     @map(\"claim_id\")\n  claim     Claim?   @relation(fields: [claimId], references: [id], onDelete: Cascade)\n  message   String   @db.Text\n  isRead    Boolean  @default(false) @map(\"is_read\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  @@map(\"notifications\")\n}\n",
